import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useScrollPosition } from '../hooks/useScrollPosition';

interface BackButtonProps {
  to?: string; // Optional fallback route if history is not available
  autoLabel?: boolean;
  customLabel?: string;
  variant?: 'primary' | 'secondary' | 'outline-primary' | 'outline-secondary' | 'outline-danger';
  className?: string;
  icon?: string;
  size?: 'sm' | 'md' | 'lg';
}

const BackButton: React.FC<BackButtonProps> = ({ 
  to, 
  autoLabel = true, 
  customLabel,
  variant = 'outline-secondary',
  className = '',
  icon = 'fas fa-arrow-left',
  size = 'md'
}) => {
  const navigate = useNavigate();
  const location = useLocation();
  const { saveCurrentPosition } = useScrollPosition();

  // Auto-generate label from current path
  const getAutoLabel = (path: string): string => {
    const pathMap: Record<string, string> = {
      '/immersivecomics/': 'Stories',
      '/product/cart/': 'Cart',
      '/product/': 'Products',
      '/': 'Home'
    };

    // Check for story management paths
    if (path.includes('/story/') && path.includes('/manage/')) {
      return 'Back to Story';
    }
    if (path.includes('/story/') && path.includes('/edit/')) {
      return 'Back to Edit';
    }
    if (path.includes('/story/') && path.includes('/create/')) {
      return 'Back to Stories';
    }
    if (path.includes('/season/') && path.includes('/create/')) {
      return 'Back to Story';
    }
    if (path.includes('/episode/') && path.includes('/create/')) {
      return 'Back to Season';
    }

    // Check for product-related paths
    if (path.includes('/product/cart/checkout/')) {
      return 'Back to Cart';
    }
    if (path.includes('/product/cart/shipping/')) {
      return 'Back to Checkout';
    }
    if (path.includes('/product/payment/')) {
      return 'Back to Shipping';
    }

    // Default fallback
    return pathMap[path] || 'Back';
  };

  const label = customLabel || (autoLabel ? getAutoLabel(location.pathname) : 'Back');

  // Size classes
  const sizeClass = size === 'sm' ? 'btn-sm' : size === 'lg' ? 'btn-lg' : '';

  const handleClick = () => {
    // Save current scroll position before navigating
    saveCurrentPosition();

    // Try to go back in history first
    // If there's no history (e.g., user came directly to page), use fallback route
    if (window.history.length > 1) {
      navigate(-1);
    } else if (to) {
      // Fallback to provided route if no history
      navigate(to);
    } else {
      // Final fallback to home
      navigate('/');
    }
  };

  return (
    <button 
      className={`btn btn-${variant} ${sizeClass} ${className}`.trim()}
      onClick={handleClick}
      style={{ padding: '0.1rem 0.4rem' }}
    >
      <i className={`${icon} me-1`}></i>     </button>
  );
};

export default BackButton;
